package main

import (
	"testing"

	"github.com/aaccioly-coding-challenges/golang-tour-solutions/internal/capture"
)

func TestPicProgram(t *testing.T) {
	output := capture.CaptureOutput(main)
	expected := "IMAGE:\n"

	if output != expected {
		t.Errorf("Expected output %q, got %q", expected, output)
	}
}
